difier and spell DC statistics increase to legendary.","availability":null,"requirements":"","prerequisites":[],"content_source_id":1},"after":{"id":34053,"cost":"","name":"Cloistered Cleric Doctrine","type":"feat","uuid":"4417862232798539","level":1,"access":"","rarity":"COMMON","traits":[3869],"actions":null,"special":"","trigger":"","version":null,"frequency":"","meta_data":{"unselectable":false},"created_at":"2024-08-20T20:27:12.959818+00:00","operations":[{"id":"9d4c8c46-1cfa-4c41-ba29-df7625bf20b9","data":{"type":"feat","abilityBlockId":20077},"type":"giveAbilityBlock"},{"id":"e4d7efd6-e947-49f6-9d63-b12ae2186d01","data":{"conditions":[{"id":"f8e9739e-be83-4e5c-b1a4-4a7733521d3e","data":{"name":"LEVEL","type":"num","value":0},"name":"LEVEL","type":"num","value":3,"operator":"GREATER_THAN_OR_EQUALS"}],"trueOperations":[{"id":"bac27b28-d9dc-4d32-bf16-7f1f142db00c","data":{"value":{"value":"E"},"variable":"SAVE_FORT"},"type":"adjValue"}],"falseOperations":[]},"type":"conditional"},{"id":"8220ffea-c65f-45e4-bc94-c9d445f38864","data":{"conditions":[{"id":"c4e03f71-fef0-401e-83fe-283c6b450937","data":{"name":"LEVEL","type":"num","value":0},"name":"LEVEL","type":"num","value":7,"operator":"GREATER_THAN_OR_EQUALS"}],"trueOperations":[{"id":"d5e24cb8-a73f-43c2-b655-9a3a29e69708","data":{"value":{"value":"E"},"variable":"SPELL_ATTACK"},"type":"adjValue"},{"id":"697c3818-cba0-49fa-9911-50f8f6e2a753","data":{"value":{"value":"E"},"variable":"SPELL_DC"},"type":"adjValue"}],"falseOperations":[]},"type":"conditional"},{"id":"e9dbcd1a-483d-49ce-b17c-3275de4b9576","data":{"conditions":[{"id":"2df76480-4dfd-41a5-83f6-4af5f6c9f46e","data":{"name":"LEVEL","type":"num","value":0},"name":"LEVEL","type":"num","value":11,"operator":"GREATER_THAN_OR_EQUALS"}],"trueOperations":[{"id":"8daf1131-96e6-4289-8602-7324ff572ad5","data":{"value":{"value":"E"},"variable":"UNARMED_ATTACKS"},"type":"adjValue"},{"id":"b8d9be07-3a42-46eb-bff7-7279a39df4d8","data":{"value":{"value":"E"},"variable":"