    union all
    select 'class_archetype:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.class_archetype r
    union all
    select 'creature:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.creature r
    union all
    select 'item:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.item r
    union all
    select 'language:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.language r
    union all
    select 'spell:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.spell r
    union all
    select 'trait:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.trait r
    union all
    select 'versatile_heritage:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.versatile_heritage r) rows; catalog_before:=all_catalog;catalog_expected:=all_catalog;
  select coalesce(jsonb_object_agg(s.id::text,to_jsonb(s)-'updated_at'),'{}'::jsonb) into all_sources from public.content_source s; sources_before:=all_sources;
  select coalesce(jsonb_agg(to_jsonb(u) order by u.id),'[]'::jsonb) into all_queue from public.content_update u; queue_before:=all_queue;
  if jsonb_build_object('item',(select count(*) from public.item where content_source_id=16),'creature',(select count(*) from public.creature where content_source_id=16),'trait',(select count(*) from public.trait where content_source_id=16)) is distinct from spec->'counts' or exists(select 1 from jsonb_array_elements(spec->'sources') s left join public.content_source r on r.id=(s->>'id')::bigint where r.id is null or (to_jsonb(r)-'updated_at') is distinct from s->'row') then raise exception 'TV display101 complete source domain changed';end if;
