  for entry in select value from jsonb_array_elements(spec->'catalog') where value->'before' is distinct from value->'after' order by value->>'table',(value->>'id')::bigint loop
    previous:=captured->((entry->>'table')||':'||(entry->>'id'));expected:=terminal->((entry->>'table')||':'||(entry->>'id'));
    if previous=expected then continue;end if;
    update public.item r set operations=typed.operations from jsonb_populate_record(null::public.item,expected) typed
      where r.id=(entry->>'id')::bigint and ((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))=previous;
    get diagnostics affected=row_count;if affected<>1 then raise exception 'TV display101 operation display CAS failed';end if;
    if entry->>'table'='ability_block' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.ability_block r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='ancestry' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.ancestry r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='archetype' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.archetype r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='class' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.class r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='creature' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.creature r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='item' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.item r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='language' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.language r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='spell' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.spell r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='trait' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.trait r where r.id=(entry->>'id')::bigint;
    else raise exception 'TV display101 unsupported catalog table';end if;
    if actual is distinct from expected then raise exception 'TV display101 operation immediate readback drift';end if;
  end loop;
  for entry in select value from jsonb_array_elements((spec->'prerequisites')||(spec->'inserts')) where jsonb_array_length(value->'display_fields')>0 order by value->>'table',value->>'uuid' loop
    if entry->>'table'='creature' then
      select count(*) into amount from public.creature r where r.uuid::text=entry->>'uuid';
      if amount<>1 then raise exception 'TV display101 UUID cardinality';end if;
      select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.creature r where r.uuid::text=entry->>'uuid';
    elsif entry->>'table'='item' then
      select count(*) into amount from public.item r where r.uuid::text=entry->>'uuid';
      if amount<>1 then raise exception 'TV display101 UUID cardinality';end if;
      select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.item r where r.uuid::text=entry->>'uuid';
    else raise exception 'TV display101 unsupported template table';end if;
    previous:=captured->((entry->>'table')||':'||(actual->>'id'));expected:=terminal->((entry->>'table')||':'||(actual->>'id'));
    if previous=expected then continue;end if;
    if entry->>'table'='item' then
      update public.item r set description=typed.description from jsonb_populate_record(null::public.item,expected) typed where r.uuid::text=entry->>'uuid' and ((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))=previous;
    elsif entry->>'table'='creature' then
      update public.creature r set details=typed.details,abilities_base=typed.abilities_base from jsonb_populate_record(null::public.creature,expected) typed where r.uuid::text=entry->>'uuid' and ((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))=previous;
    else raise exception 'TV display101 unsupported authored write';end if;
    get diagnostics affected=row_count;if affected<>1 then raise exception 'TV display101 authored display CAS failed';end if;
    if entry->>'table'='creature' then
      select count(*) into amount from public.creature r where r.uuid::text=entry->>'uuid';
      if amount<>1 then raise exception 'TV display101 UUID cardinality';end if;
      select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.creature r where r.uuid::text=entry->>'uuid';
    elsif entry->>'table'='item' then
      select count(*) into amount from public.item r where r.uuid::text=entry->>'uuid';
      if amount<>1 then raise exception 'TV display101 UUID cardinality';end if;
      select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.item r where r.uuid::text=entry->>'uuid';
    else raise exception 'TV display101 unsupported template table';end if;
    if actual is distinct from expected then raise exception 'TV display101 authored immediate readback drift';end if;
  end loop;
  for entry in select value from jsonb_array_elements(spec->'catalog') loop
    if entry->>'table'='ability_block' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.ability_block r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='ancestry' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.ancestry r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='archetype' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.archetype r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='class' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.class r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='creature' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.creature r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='item' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.item r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='language' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.language r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='spell' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.spell r where r.id=(entry->>'id')::bigint;
    elsif entry->>'table'='trait' then select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.trait r where r.id=(entry->>'id')::bigint;
    else raise exception 'TV display101 unsupported catalog table';end if;
    if actual is distinct from terminal->((entry->>'table')||':'||(entry->>'id')) then raise exception 'TV display101 final catalog drift';end if;
  end loop;
  for entry in select value from jsonb_array_elements((spec->'prerequisites')||(spec->'inserts')) loop
    if entry->>'table'='creature' then
      select count(*) into amount from public.creature r where r.uuid::text=entry->>'uuid';
      if amount<>1 then raise exception 'TV display101 UUID cardinality';end if;
      select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.creature r where r.uuid::text=entry->>'uuid';
    elsif entry->>'table'='item' then
      select count(*) into amount from public.item r where r.uuid::text=entry->>'uuid';
      if amount<>1 then raise exception 'TV display101 UUID cardinality';end if;
      select (to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text) into actual from public.item r where r.uuid::text=entry->>'uuid';
    else raise exception 'TV display101 unsupported template table';end if;
    if actual is distinct from terminal->((entry->>'table')||':'||(actual->>'id')) then raise exception 'TV display101 final allocated full-row drift';end if;
  end loop;
  for entry in select jsonb_build_object('key',key,'value',value) from jsonb_each(terminal) loop
    catalog_expected:=jsonb_set(catalog_expected,array[entry->>'key'],to_jsonb(md5((entry->'value')::text)),false);
  end loop;
  select coalesce(jsonb_object_agg(k,v),'{}'::jsonb) into all_catalog from (select 'ability_block:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.ability_block r
    union all
    select 'ancestry:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.ancestry r
    union all
    select 'archetype:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.archetype r
    union all
    select 'background:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.background r
    union all
    select 'class:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.class r
    union all
    select 'class_archetype:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.class_archetype r
    union all
    select 'creature:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.creature r
    union all
    select 'item:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.item r
    union all
    select 'language:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.language r
    union all
    select 'spell:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.spell r
    union all
    select 'trait:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.trait r
    union all
    select 'versatile_heritage:'||r.id::text as k,to_jsonb(md5(((to_jsonb(r)-'updated_at'-'search_tsv')||jsonb_build_object('uuid',r.uuid::text))::text)) as v from public.versatile_heritage r) rows;
  if all_catalog is distinct from catalog_expected then raise exception 'TV display101 complete catalog preservation drift';end if;
  select coalesce(jsonb_object_agg(s.id::text,to_jsonb(s)-'updated_at'),'{}'::jsonb) into all_sources from public.content_source s;
  if all_sources is distinct from sources_before then raise exception 'TV display101 whole source preservation drift';end if;
  select coalesce(jsonb_agg(to_jsonb(u) order by u.id),'[]'::jsonb) into all_queue from public.content_update u;
  if all_queue is distinct from queue_before then raise exception 'TV display101 whole queue preservation drift';end if;
  if jsonb_build_object('item',(select count(*) from public.item where content_source_id=16),'creature',(select count(*) from public.creature where content_source_id=16),'trait',(select count(*) from public.trait where content_source_id=16)) is distinct from spec->'counts' or exists(select 1 from jsonb_array_elements(spec->'sources') s left join public.content_source r on r.id=(s->>'id')::bigint where r.id is null or (to_jsonb(r)-'updated_at') is distinct from s->'row') or exists(select 1 from jsonb_array_elements((spec->'prerequisites')||(spec->'inserts')) p join public.item r on r.content_source_id=16 and lower(btrim(r.name))=lower(btrim(p->>'name')) where p->>'table'='item' and r.uuid::text<>p->>'uuid') or exists(select 1 from jsonb_array_elements(spec->'prerequisites') p join public.creature r on r.content_source_id=16 and lower(btrim(r.name))=lower(btrim(p->>'name')) where p->>'table'='creature' and r.uuid::text<>p->>'uuid') or exists(select 1 from jsonb_array_elements(spec->'known_pending_dependencies') known join public.content_update u on u.id=(known->>'id')::bigint where not (u.id=(known->>'id')::bigint and u.type=known->>'type' and u.ref_id=(known->>'ref_id')::bigint and u.content_source_id=(known->>'content_source_id')::bigint and upper(btrim(coalesce(u.status->>'state','PENDING')))=known->>'state' and jsonb_build_object('id',u.data->'id','name',u.data->'name','uuid',u.data->'uuid','content_source_id',u.data->'content_source_id')=known->'identity' and md5(to_jsonb(u)::text)=known->>'complete_row_md5')) or exists(select 1 from public.content_update u where upper(btrim(coalesce(u.status->>'state','PENDING'))) not in('APPROVED','REJECTED') and (exists(select 1 from jsonb_array_elements(spec->'catalog') p where (u.type=p->>'type' or (p->>'table'='ability_block' and u.type='ability-block')) and (u.ref_id=(p->>'id')::bigint or u.data->>'id'=p->>'id' or u.data->>'uuid'=p#>>'{before,uuid}' or ((u.content_source_id=(p#>>'{before,content_source_id}')::bigint or u.data->>'content_source_id'=p#>>'{before,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(p#>>'{before,name}'))) or (coalesce(btrim(u.data#>>'{meta_data,source,url}'),'')<>'' and lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(p#>>'{before,meta_data,source,url}'))))) or exists(select 1 from jsonb_array_elements((spec->'prerequisites')||(spec->'inserts')) p where u.type=p->>'type' and (u.data->>'uuid'=p->>'uuid' or exists(select 1 from public.item r where p->>'table'='item' and r.uuid::text=p->>'uuid' and (u.ref_id=r.id or u.data->>'id'=r.id::text)) or exists(select 1 from public.creature r where p->>'table'='creature' and r.uuid::text=p->>'uuid' and (u.ref_id=r.id or u.data->>'id'=r.id::text)) or ((u.content_source_id=16 or u.data->>'content_source_id'='16') and (lower(btrim(u.data->>'name'))=lower(btrim(p->>'name')) or exists(select 1 from jsonb_array_elements(coalesce(p->'aliases','[]')) a cross join lateral jsonb_array_elements_text(a->'names') name where btrim(regexp_replace(lower(u.data->>'name'),'[^a-z0-9]+',' ','g')) like name.value||'%'))) or (coalesce(btrim(p#>>'{row,meta_data,source,url}'),'')<>'' and lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(p#>>'{row,meta_data,source,url}'))) or exists(select 1 from jsonb_array_elements(coalesce(p->'aliases','[]')) a cross join lateral jsonb_array_elements_text(a->'citation_ids') c(id) where coalesce(btrim(u.data#>>'{meta_data,source,url}'),'') ~* '^https?://2e[.]aonprd[.]com/Equipment[.]aspx[?]' and substring(lower(btrim(u.data#>>'{meta_data,source,url}')) from '[?&]id=([0-9]+)')=c.id))) or exists(select 1 from jsonb_array_elements(spec->'sources') s where u.type='content-source' and (u.ref_id=(s->>'id')::bigint or u.data->>'id'=s->>'id' or lower(btrim(u.data->>'name'))=lower(btrim(s->>'name')) or (coalesce(btrim(s#>>'{row,url}'),'')<>'' and lower(btrim(s#>>'{row,url}')) in(lower(btrim(u.data->>'url')),lower(btrim(u.data#>>'{meta_data,source,url}'))))))) and not exists(select 1 from jsonb_array_elements(spec->'known_pending_dependencies') known where u.id=(known->>'id')::bigint and u.type=known->>'type' and u.ref_id=(known->>'ref_id')::bigint and u.content_source_id=(known->>'content_source_id')::bigint and upper(btrim(coalesce(u.status->>'state','PENDING')))=known->>'state' and jsonb_build_object('id',u.data->'id','name',u.data->'name','uuid',u.data->'uuid','content_source_id',u.data->'content_source_id')=known->'identity' and md5(to_jsonb(u)::text)=known->>'complete_row_md5')) then raise exception 'TV display101 final closure drift';end if;
end $repair$;
$display_original_source$;
end $display_source_successor$;
